package net.civeira.phylax.feature.observe.observeddashboard.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboard;
import net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject.SourceVariableVO;

class SourceVariableValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of source variable of observed dashboard")
  void test_source_variable_value_holder_assign_plain_value() {
    Object holder = new Object();
    SourceVariableValueHolder<Object> value = new SourceVariableValueHolder<>(holder);
    Assertions.assertSame(holder, value.sourceVariable(true), "Setters must return the holder");
    Assertions.assertTrue(value.getSourceVariableValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getSourceVariable().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of source variable of observed dashboard")
  void test_source_variable_value_holder_assign_value_object() {
    Object holder = new Object();
    SourceVariableValueHolder<Object> value = new SourceVariableValueHolder<>(holder);
    SourceVariableVO vo = SourceVariableVO.from(true);
    Assertions.assertFalse(value.getSourceVariableValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.sourceVariable(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSourceVariableValue().orElseThrow());
    Assertions.assertSame(holder, value.sourceVariable(Optional.empty()));
    Assertions.assertFalse(value.getSourceVariableValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.sourceVariable(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSourceVariableValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of source variable of observed dashboard against the original")
  void test_source_variable_value_holder_read() {
    Object holder = new Object();
    SourceVariableValueHolder<Object> value = new SourceVariableValueHolder<>(holder);
    SourceVariableVO vo = SourceVariableVO.from(true);
    SourceVariableVO other = SourceVariableVO.from(true);
    ObservedDashboard original = Mockito.mock(ObservedDashboard.class);
    Mockito.when(original.getSourceVariableValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSourceVariable(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readSourceVariable(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.sourceVariable(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSourceVariable(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSourceVariable(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of source variable of observed dashboard")
  void test_source_variable_value_holder_unset() {
    Object holder = new Object();
    SourceVariableValueHolder<Object> value = new SourceVariableValueHolder<>(holder);
    SourceVariableVO vo = SourceVariableVO.from(true);
    value.sourceVariable(vo);
    Assertions.assertSame(holder, value.unsetSourceVariableIfMatches("sourceVariable_other"));
    Assertions.assertTrue(value.getSourceVariableValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSourceVariableIfMatches("sourceVariable"));
    Assertions.assertFalse(value.getSourceVariableValue().isPresent(),
        "The field name must clear the value");
    value.sourceVariable(vo);
    Assertions.assertSame(holder, value.unsetSourceVariable());
    Assertions.assertFalse(value.getSourceVariableValue().isPresent(),
        "Unset must clear the value");
  }
}
